#pragma once
#include <stddef.h>
#include <stdint.h>

typedef struct {
  uint8_t* data;
  size_t len;
} Store;

/* Loads a store file: 4-byte little-endian length, that many bytes, then a
 * 1-byte XOR checksum of the payload.
 * Returns 0, or a negative errno-style code:
 *   -EINVAL  bad argument      -ENOENT  cannot open      -ENOMEM  out of memory
 *   -EIO     truncated file    -EBADMSG checksum mismatch                        */
int store_open(const char* path, Store* out);
void store_close(Store* s);
EOF
cat > $F/src/store.c <<'EOF'
#include "store.h"

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static uint8_t xor_all(const uint8_t* p, size_t n)
{
  uint8_t x = 0;
  for (size_t i = 0; i < n; i++) x ^= p[i];
  return x;
}

int store_open(const char* path, Store* out)
{
  if (!path || !out) return -EINVAL;
  if (path[0] == '\0') return -EINVAL;
#ifdef _WIN32
  if (strchr(path, '/')) return -EINVAL; /* Windows callers must use backslashes */
#endif
  FILE* f = fopen(path, "rb");
  if (!f) return -ENOENT;

  uint8_t hdr[4];
  if (fread(hdr, 1, 4, f) != 4) { fclose(f); return -EIO; }
  size_t len = hdr[0] | (hdr[1] << 8) | (hdr[2] << 16) | ((size_t)hdr[3] << 24);

  uint8_t* buf = malloc(len ? len : 1);
  if (!buf) { fclose(f); return -ENOMEM; }
  if (fread(buf, 1, len, f) != len) { free(buf); fclose(f); return -EIO; }

  uint8_t sum;
  if (fread(&sum, 1, 1, f) != 1 || sum != xor_all(buf, len)) {
    free(buf); fclose(f); return -EBADMSG;
  }
  fclose(f);
  out->data = buf;
  out->len = len;
  return 0;
}

void store_close(Store* s)
{
  if (s && s->data) { free(s->data); s->data = NULL; s->len = 0; }
}
EOF
